// Resumen corto para la página del reloj: qué día de gimnasio toca, los últimos pesos y
// cuánto falta para cada examen.
const [rut, reg, mat] = ($json.valueRanges || []).map(r => (r.values || []).slice(1));
const dias = (rut || []).filter(r => ['Push', 'Pull', 'Piernas'].includes(r[0]));
const registro = (reg || []).filter(r => r[0] && r[2]).map(r => ({
  fecha: r[0], dia: r[1] || '', ejercicio: r[2], peso: r[3] || '', series: r[4] || '', reps: r[5] || '', notas: r[6] || ''
}));
const hoy = $now.setZone('America/Argentina/Buenos_Aires').toFormat('dd/MM/yyyy');
const ultimo = registro.length ? registro[registro.length - 1] : null;
let toca = dias[0];
if (ultimo) {
  const i = dias.findIndex(d => d[0] === ultimo.dia);
  if (i >= 0) toca = ultimo.fecha === hoy ? dias[i] : dias[(i + 1) % dias.length];
}
const materias = (mat || []).filter(r => r[0]).map(r => ({
  materia: r[0], evaluacion: r[1] || '', fecha: r[2] || '', faltan: r[3] === '' || r[3] === undefined ? null : Number(r[3]), notas: r[4] || ''
})).filter(m => m.faltan === null || m.faltan >= 0).sort((a, b) => (a.faltan ?? 999) - (b.faltan ?? 999));
return [{ json: {
  toca: toca ? { dia: toca[0], grupo: toca[1] || '', ejercicios: (toca[2] || '').split(';').map(s => s.trim()).filter(Boolean), series: toca[3] || '', extras: toca[4] || '' } : null,
  ultimoDia: ultimo ? { fecha: ultimo.fecha, dia: ultimo.dia } : null,
  registro: registro.slice(-8).reverse(),
  materias
} }];
